// #62038e מסך מסמכים קבועים של החברה — тексты по Figma 1141:1923 (реджект rej_00014f2a…, принято 18.11.2026):
// вкладка «מסמכים קבועים» профиля (/onboarding, tablist «פרופיל החברה») и шаг 4 мастера (мок «сервер в памяти»).
// Только чтение: ничего не загружается и не меняется. Запись в Supabase перехватывается и считается (должно быть 0).
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { authState } from '../helpers/tenderflow';
import { clickAndSaveTaqo, expectTaqoStep, mockWizardServer } from '../onboarding-wizard/wizard-mock';

// 18.11.2026: кнопка перехода в мастере называется «המשך לשלב הבא» (TAQO_NEXT='המשך' из wizard-mock устарел).
const NEXT_STEP = 'המשך לשלב הבא';

const HINT =
  'מומלץ להעלות קבצי PDF תקניים (תומך גם ב-JPG, PNG עד 20 MB לקובץ) • ניתן להעלות מספר קבצים במקביל — TAQO תמיין אותם לתיקיות ותזהה תוקף אוטומטית.';
const LIST_HEADING = 'רשימת המסמכים המותאמת לחברה';
const GROUP_A = 'א׳ · מסמכי יסוד כלליים — חובה ברוב המכרזים';
const GROUP_B = 'ב׳ · מסמכים ייעודיים לתחום הפעילות שלך — לפי שלבים 1–2';
const TYPES_A = [
  'תעודת התאגדות',
  'נסח חברה עדכני (רשם החברות)',
  'אישור ניהול ספרים וניכוי מס במקור',
  'פרוטוקול מורשי חתימה (מאומת ע״י עו״ד)',
  'אישור רו״ח — מחזורי הכנסות',
  'תצהיר ייצוג הולם לאנשים עם מוגבלות (סעיף 2ב1)',
];
const TYPES_B = ['תעודת ISO 9001', 'רישיון קבלן רשום', 'פוליסת ביטוח צד ג׳ וחבות מעבידים'];
const FILE_21MB = path.resolve(__dirname, '../../../test-files/qa-62038e-21mb.pdf');

/** NBSP и повторные пробелы → обычный пробел (Figma/верстка могут вставлять неразрывные). */
const norm = (s: string | null | undefined) => (s ?? '').replace(/[  ]/g, ' ').replace(/\s+/g, ' ').trim();

/** Любая запись в Supabase (rest/storage) не уходит на сервер и фиксируется. */
async function blockWrites(page: Page) {
  const writes: string[] = [];
  await page.route(/supabase\.co\/(rest|storage)\/v1\//, (route) => {
    const r = route.request();
    if (!['GET', 'HEAD', 'OPTIONS'].includes(r.method())) {
      writes.push(`${r.method()} ${r.url()}`);
      return route.abort();
    }
    return route.fallback();
  });
  return writes;
}

async function openProfileDocsTab(page: Page) {
  await page.goto('/onboarding');
  await expect(page.getByRole('tablist', { name: 'פרופיל החברה' })).toBeVisible();
  const tab = page.getByRole('tab', { name: /^מסמכים קבועים/ });
  await tab.click();
  await expect(tab).toHaveAttribute('aria-selected', 'true');
  await expect(page.getByRole('heading', { name: LIST_HEADING })).toBeVisible();
}

/** Шаг 4 мастера у «новой» компании (мок): «המשך» ×3 без сохранения на сервер. */
async function openWizardDocsStep(page: Page) {
  const server = await mockWizardServer(page, { fresh: true });
  await page.goto('/onboarding');
  await expectTaqoStep(page, 1);
  for (const n of [2, 3, 4]) {
    await clickAndSaveTaqo(page, server, NEXT_STEP);
    await expectTaqoStep(page, n);
  }
  await expect(page.getByRole('heading', { name: LIST_HEADING })).toBeVisible();
  return server;
}

/** Общая проверка текстов экрана по Figma 1141:1923 (одинакова для вкладки профиля и шага 4). */
async function expectVaultTexts(page: Page) {
  await expect(page.getByText('גרור לכאן קבצים או בחר מהמחשב', { exact: true })).toBeVisible();
  await expect.poll(async () => norm(await page.locator('#permanent-docs-hint').textContent())).toBe(HINT);
  await expect(page.locator('#permanent-docs-hint')).toBeVisible();
  // Старые тексты исчезли
  await expect(page.getByText('רשימת המסמכים הנדרשים', { exact: true })).toHaveCount(0);
  await expect(page.getByText(/Word ו-Excel/)).toHaveCount(0);

  await expect(page.getByRole('heading', { name: LIST_HEADING, exact: true })).toBeVisible();
  const gA = page.getByRole('heading', { name: GROUP_A, exact: true });
  const gB = page.getByRole('heading', { name: GROUP_B, exact: true });
  await expect(gA).toBeVisible();
  await expect(gB).toBeVisible();
  // Старый заголовок группы ב׳ без «לפי שלבים 1–2» не допускается
  await expect(page.getByText('ב׳ · מסמכים ייעודיים לתחום הפעילות', { exact: true })).toHaveCount(0);

  // 9 типов: 6 в группе א׳ и 3 в группе ב׳ (по порядку на странице)
  const all = [...TYPES_A, ...TYPES_B];
  for (const t of all) await expect(page.getByText(t, { exact: true }).first(), `тип «${t}»`).toBeVisible();
  const ys: number[] = [];
  for (const t of all) ys.push((await page.getByText(t, { exact: true }).first().boundingBox())!.y);
  const yA = (await gA.boundingBox())!.y;
  const yB = (await gB.boundingBox())!.y;
  TYPES_A.forEach((_, i) => { expect(ys[i], `«${all[i]}» после א׳`).toBeGreaterThan(yA); expect(ys[i], `«${all[i]}» до ב׳`).toBeLessThan(yB); });
  TYPES_B.forEach((_, i) => expect(ys[TYPES_A.length + i], `«${TYPES_B[i]}» после ב׳`).toBeGreaterThan(yB));

  // Счётчик «X מתוך 9 הועלו» и бейдж «X / 9»: X из 0..9, одинаковый
  const counter = page.getByText(/^\s*\d+ מתוך 9 הועלו/);
  await expect(counter).toBeVisible();
  const x = Number(norm(await counter.textContent()).match(/^(\d+) מתוך 9/)![1]);
  expect(x).toBeGreaterThanOrEqual(0);
  expect(x).toBeLessThanOrEqual(9);
  await expect(page.getByText(new RegExp(`^\\s*${x}\\s*/\\s*9\\s*$`))).toBeVisible();
}

test.describe('מסך מסמכים קבועים — טקסטים לפי Figma #62038e', () => {
  test.use({ storageState: authState('admin') });

  test('לשונית "מסמכים קבועים" בפרופיל: הנחיית העלאה, כותרות, קבוצות ו-9 סוגי מסמכים #62038e @desktop @prod-safe', async ({ page }) => {
    const writes = await blockWrites(page);
    await openProfileDocsTab(page);
    await expectVaultTexts(page);
    expect(writes).toEqual([]);
  });

  test('שלב 4 באשף (חשבון חדש, מוק): אותם טקסטים, קבוצות ו-9 סוגי מסמכים #62038e @desktop @prod-safe', async ({ page }) => {
    const server = await openWizardDocsStep(page);
    await expectVaultTexts(page);
    expect(server.blockedWrites).toEqual([]);
  });

  test('קובץ 21MB נדחה בצד הלקוח בלי בקשת העלאה, וקובץ גדול מ-20MB אינו נוסף לרשימה #62038e @desktop @prod-safe', async ({ page }) => {
    const writes = await blockWrites(page);
    await openProfileDocsTab(page);
    const counter = page.getByText(/^\s*\d+ מתוך 9 הועלו/);
    const before = norm(await counter.textContent());

    await page.locator('#permanent-docs').setInputFiles(FILE_21MB);
    await expect(page.getByRole('alert').filter({ hasText: 'qa-62038e-21mb.pdf גדול מדי' })).toContainText('עד 20MB לקובץ');
    await expect(page.getByText('qa-62038e-21mb.pdf', { exact: true })).toHaveCount(0);
    expect(norm(await counter.textContent())).toBe(before);
    // Ни одна запись (в т.ч. загрузка в storage) не была отправлена
    expect(writes).toEqual([]);
  });
});

test.describe('מסך מסמכים קבועים — פריסה ב-390px #62038e', () => {
  test.use({ storageState: authState('admin'), viewport: { width: 390, height: 844 } });

  test('ב-390px אין גלילה אופקית, הנחיה, כותרות ושורות המסמכים נכנסים למסך #62038e @desktop @prod-safe', async ({ page }) => {
    const writes = await blockWrites(page);
    await openProfileDocsTab(page);
    await expect(page.getByRole('heading', { name: GROUP_A, exact: true })).toBeVisible();
    await expect(page.getByRole('heading', { name: GROUP_B, exact: true })).toBeVisible();

    // нет горизонтальной прокрутки страницы
    const sizes = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth }));
    expect(sizes.sw).toBeLessThanOrEqual(sizes.cw);

    // подсказка, заголовки групп, названия типов и счётчик целиком в пределах 390px
    const inView = [
      page.locator('#permanent-docs-hint'),
      page.getByRole('heading', { name: LIST_HEADING, exact: true }),
      page.getByRole('heading', { name: GROUP_A, exact: true }),
      page.getByRole('heading', { name: GROUP_B, exact: true }),
      page.getByText(/^\s*\d+ מתוך 9 הועלו/),
      ...[...TYPES_A, ...TYPES_B].map((t) => page.getByText(t, { exact: true }).first()),
    ];
    for (const loc of inView) {
      const box = (await loc.boundingBox())!;
      expect(box.x, 'левый край').toBeGreaterThanOrEqual(0);
      expect(box.x + box.width, 'правый край').toBeLessThanOrEqual(390);
    }

    // у загруженных файлов имя и дата («נוסף ב-dd.mm.yyyy») не обрезаны и не выходят за экран
    const dates = page.getByText(/^נוסף ב-\d{2}\.\d{2}\.\d{4}$/);
    const n = await dates.count();
    for (let i = 0; i < n; i++) {
      const box = (await dates.nth(i).boundingBox())!;
      expect(box.x).toBeGreaterThanOrEqual(0);
      expect(box.x + box.width).toBeLessThanOrEqual(390);
    }
    expect(writes).toEqual([]);
  });
});
